contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address receiver, uint amount) public payable {
        // Ensure this test contract is NOT the owner; the owner is the deployer of c,
        // which is this test contract only if it was deployed by us. In the checker,
        // the owner is set at deployment. We cannot control ownership, but we can
        // reason: the test contract deploys c, so msg.sender for c's constructor
        // is this test contract? No, the checker deploys c fresh and passes it.
        // Actually the constructor of C sets owner = payable(msg.sender) at deployment.
        // The InvMutTest contract is deployed first, then C is deployed by the checker
        // (or by the test contract? The constructor takes _c).
        // The prompt says: the checker deploys a FRESH c and runs run(...) once;
        // msg.sender is the InvMutTest contract for every call on c, and this contract deployed c.
        // So owner = address(this) (the InvMutTest contract).
        // Therefore sendTo from this contract WILL be from the owner and may succeed.
        // To test the non-owner revert rule, we need a caller that is not the owner.
        // But we cannot change msg.sender inside run; all calls from run are from this contract.
        // Therefore we cannot directly test the non-owner case via sendTo from run.
        // Alternative: we can check that when called by the owner (this contract), the call
        // succeeds and transfers the amount, provided the receiver can accept Ether and
        // c has enough balance. But the previous accepted rule already covers that.
        // Since we must not repeat accepted rules, and our previous rule was wrong because
        // the owner is this contract (so it succeeded), we can instead write a rule about
        // the revert condition based on amount and balance: if c's balance is insufficient,
        // the call reverts. But note: even if insufficient, the transfer will revert due to
        // insufficient balance. However, the owner check passes because we are the owner.
        // So we can test: if amount > address(c).balance, then sendTo reverts.
        // And if amount <= address(c).balance and receiver is an EOA (not contract), it succeeds.
        // But we need a general rule that holds for all inputs.
        // Let's write: For any call to sendTo by the owner, the call reverts if and only if
        // the amount exceeds c's balance or the receiver rejects Ether.
        // But that's complex to express without knowing receiver's nature.
        // Simpler: when amount > address(c).balance, the call always reverts.
        // This is a valid rule: require(amount > address(c).balance); then assert reverted.
        // However, we must ensure we don't start with a precondition that is impossible.
        // We can set amount to be larger than balance using a parameter and require.
        // Let's do: require(amount > address(c).balance); then call sendTo, expect revert.
        // But we also need to ensure the owner check passes (we are owner). That's fine.
        // But note: if amount is huge, transfer will fail due to insufficient balance.
        // However, there is a catch: if receiver is a contract that reverts, it would also revert.
        // That's still consistent: the rule says "if amount > balance, then reverts" - true regardless.
        // So we can assert reverted when amount > balance.
        // But we must also handle the case where amount <= balance? We could assert not reverted
        // only if receiver can accept; but we can't know. So we focus on the insufficient balance case.
        // Let's write: require(amount > address(c).balance);
        // Then call sendTo, bool reverted; assert(reverted);
        // This is a general rule: whenever the owner calls sendTo with amount greater than the
        // contract's balance, the call reverts.
        // Check that this holds: yes, transfer will revert due to insufficient balance.
        // Also note: the owner check passes because we are the owner.
        // So the only reason to revert is insufficient balance or receiver reverting.
        // But if amount > balance, it definitely reverts.
        // So assert reverted is true.
        // This is a valid rule.
        // However, the checker might try to prove it for all inputs; we have a precondition.
        // That's allowed.
        // We need to ensure we don't read msg.value; we don't.
        // We don't need to send Ether from the test; the call to sendTo doesn't require value.
        // The function is not payable? sendTo is not marked payable, so we cannot send value.
        // So we call c.sendTo(receiver, amount) without value.
        // The contract c may have some balance from deployment? We can assume it has some balance.
        // But we cannot guarantee c has balance > 0. The constructor doesn't set any balance.
        // However, the test contract can send Ether to c? We can't send Ether to c directly
        // because we only interact through c's public functions. sendTo is the only way to move Ether out.
        // But we can send Ether to c by calling a payable function? c has no payable functions.
        // So c's balance might be zero initially. Then amount > 0 > balance, so amount > balance holds for any amount > 0.
        // But if amount is 0 and balance is 0, then amount > balance is false.
        // We can require(amount > address(c).balance). If balance is 0, then amount must be > 0.
        // That's fine. The checker will consider all possible balances of c? Actually c is deployed fresh;
        // its balance is 0 unless the constructor sends Ether. The constructor does not send Ether.
        // So address(c).balance is 0. Then require(amount > 0) is needed.
        // But the checker might consider that c could have received Ether? No, because the only way to receive
        // is via a payable function or selfdestruct, none exist. So balance is always 0.
        // Then the rule: if amount > 0, sendTo reverts. Is that true? Yes, because transfer of amount > 0
        // from balance 0 will fail. But wait: the owner check passes (we are owner). Then it attempts
        // payable(receiver).transfer(amount). If receiver is an EOA, transfer will try to send amount
        // from c's balance. If c's balance is 0, it will revert. If receiver is a contract that
        // can receive Ether, it still needs funds. So yes, it reverts.
        // So the rule holds: for any amount > 0, sendTo reverts.
        // But what if amount is 0? Then transfer of 0 might succeed (if receiver accepts). But we can exclude
        // by requiring amount > 0.
        // So we can do: require(amount > address(c).balance); then call, assert reverted.
        // This is a general rule.
        // But is it interesting? It tests the insufficient balance revert condition.
        // The accepted rule already covers the success case. This is a different rule.
        // Let's implement.
        require(amount > address(c).balance, "amount must exceed balance");
        bool reverted;
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted);
    }

    receive() external payable {}
}

